            policyDb = container "Policy Database" "Stores policy and cover records" "Relational database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Relational database" "Database"
            documentStore = container "Document Store" "Holds claim photos, reports, and correspondence" "Object storage" "File Store"
        }

        claimsDataBureau = softwareSystem "National Claims Data Bureau" "A national claims data bureau operated by a different organization" "External"
        clearingHouse = softwareSystem "Clearing House" "A clearing house operated by a different organization" "External"

        policyholder -> claimsCenter.webPortal "reports claims and tracks progress" "HTTPS"
        policyholder -> claimsCenter.mobileAppBackend "reports claims and tracks progress via the mobile app" "HTTPS"

        claimsCenter.webPortal -> claimsCenter.intake "submits new claims to" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.assessment "requests settlement amounts from" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.payout "requests settlements from" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.document "uploads claim photos and reports to" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.notification "requests status updates from" "HTTPS"

        claimsCenter.mobileAppBackend -> claimsCenter.intake "submits new claims to" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.assessment "requests settlement amounts from" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.payout "requests settlements from" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.document "uploads claim photos and reports to" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.notification "requests status updates from" "HTTPS"

        claimsCenter.intake -> claimsCenter.triage "hands accepted claims to" "HTTP"
        claimsCenter.triage -> claimsCenter.assessment "routes claims to" "HTTP"
        claimsCenter.assessment -> claimsCenter.payout "requests settlements from" "HTTP"

        claimsCenter.intake -> claimsCenter.fraudScreening "sends each incoming claim to for screening" "HTTP"
        claimsCenter.intake -> claimsCenter.policyVerification "sends each incoming claim to for cover checks" "HTTP"
        claimsCenter.intake -> claimsCenter.assignment "sends each incoming claim to for routing" "HTTP"
        claimsCenter.assignment -> claimsCenter.adjusterWorkbench "routes the claim to" "HTTP"

        claimsCenter.fraudScreening -> claimsDataBureau "consults" "HTTPS"
        claimsCenter.payout -> clearingHouse "executes settlements through" "HTTPS"

        claimsCenter.document -> claimsCenter.documentStore "reads from"
        claimsCenter.batchScheduler -> claimsCenter.claimsDb "reads and writes" "SQL"
        claimsCenter.batchScheduler -> claimsCenter.policyDb "reads and writes" "SQL"

        claimsCenter.notification -> policyholder "reports claim status changes to" "Email, SMS"
    }

    views {
        systemContext claimsCenter "SystemContext" {
            include *
            autoLayout
            title "System Context for Claims Center"
        }

        container claimsCenter "Containers" {
